function alienOrder(words: string[]): string {
  const next = new Map<string, Set<string>>()
  const indegree = new Map<string, number>()
  for (const w of words) for (const ch of w) {
    if (!next.has(ch)) next.set(ch, new Set())
    if (!indegree.has(ch)) indegree.set(ch, 0)
  }
  for (let i = 0; i + 1 < words.length; i++) {
    const a = words[i]
    const b = words[i + 1]
    if (a.length > b.length && a.startsWith(b)) return ''
    for (let j = 0; j < Math.min(a.length, b.length); j++) {
      if (a[j] !== b[j]) {
        if (!next.get(a[j])!.has(b[j])) {
          next.get(a[j])!.add(b[j])
          indegree.set(b[j], indegree.get(b[j])! + 1)
        }
        break
      }
    }
  }
  const ready = [...indegree].filter(([, d]) => d === 0).map(([ch]) => ch).sort()
  let order = ''
  while (ready.length) {
    const ch = ready.shift()!
    order += ch
    for (const n of next.get(ch)!) {
      indegree.set(n, indegree.get(n)! - 1)
      if (indegree.get(n) === 0) {
        ready.push(n)
        ready.sort()
      }
    }
  }
  return order.length === indegree.size ? order : ''
}
